import { useState, type FormEvent } from 'react';
import { Button, Field, Input, Select, Switch } from '@jinx-ui/react';

export type ProfileLanguage = 'ru' | 'en';

export type ProfileSettings = {
  name: string;
  language: ProfileLanguage;
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
};

const LANGUAGE_OPTIONS: ReadonlyArray<{ value: ProfileLanguage; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileLanguage>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const trimmedName = name.trim();

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSave({ name: trimmedName, language, emailNotifications });
  }

  return (
    <form
      className="jx-stack jx-card"
      style={{ gap: 'var(--jx-space-4)', padding: 'var(--jx-space-5)' }}
      onSubmit={handleSubmit}
      aria-labelledby="profile-settings-title"
    >
      <h2 id="profile-settings-title" className="jx-heading">
        Настройки профиля
      </h2>

      <Field label="Имя" htmlFor="profile-name">
        <Input
          id="profile-name"
          name="name"
          value={name}
          autoComplete="name"
          placeholder="Введите имя"
          onChange={(event) => setName(event.target.value)}
        />
      </Field>

      <Field label="Язык интерфейса" htmlFor="profile-language">
        <Select
          id="profile-language"
          name="language"
          value={language}
          options={LANGUAGE_OPTIONS}
          onChange={(value: ProfileLanguage) => setLanguage(value)}
        />
      </Field>

      <Switch
        id="profile-email-notifications"
        name="emailNotifications"
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(checked: boolean) => setEmailNotifications(checked)}
      />

      <div className="jx-row" style={{ gap: 'var(--jx-space-3)' }}>
        <Button type="submit" variant="primary" disabled={trimmedName.length === 0}>
          Сохранить
        </Button>
      </div>
    </form>
  );
}

